// Improved Dashboard Component
// File: frontend/src/pages/Dashboard_IMPROVED.jsx
// Better state management, error handling, loading states

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getTransactions, isLoggedIn } from '../services/api';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import Navbar from '../components/Navbar';
import './Dashboard.css';

function Dashboard() {
  // State management
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showForm, setShowForm] = useState(false);

  const navigate = useNavigate();

  // Check authentication on component mount
  useEffect(() => {
    if (!isLoggedIn()) {
      navigate('/login');
      return;
    }

    // Fetch transactions
    loadTransactions();
  }, [navigate]);

  // Fetch transactions from backend
  const loadTransactions = async () => {
    try {
      setLoading(true);
      setError('');

      const data = await getTransactions();
      setTransactions(data);
    } catch (err) {
      // Handle specific error codes
      if (err.code === 'TOKEN_EXPIRED') {
        setError('Your session expired. Please login again.');
        navigate('/login');
      } else if (err.code === 'NO_TOKEN') {
        navigate('/login');
      } else {
        setError('Failed to load transactions. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  // Called after successful transaction add
  const handleTransactionAdded = () => {
    // Refresh the list
    loadTransactions();
    setShowForm(false);
  };

  // Delete transaction
  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this transaction?')) {
      return;
    }

    try {
      // Remove from state immediately (optimistic update)
      setTransactions(transactions.filter((t) => t.id !== id));
      // Note: The delete is handled in TransactionList component

    } catch (err) {
      setError('Failed to delete transaction');
      // Reload to sync
      loadTransactions();
    }
  };

  // Calculate summary statistics
  const calculateStats = () => {
    const stats = {
      totalIncome: 0,
      totalExpense: 0,
      balance: 0,
    };

    transactions.forEach((t) => {
      if (t.type === 'income') {
        stats.totalIncome += parseFloat(t.amount);
      } else {
        stats.totalExpense += parseFloat(t.amount);
      }
    });

    stats.balance = stats.totalIncome - stats.totalExpense;
    return stats;
  };

  const stats = calculateStats();

  return (
    <div>
      <Navbar />

      <div className="dashboard-container">
        <h1>Finance Dashboard</h1>

        {/* Error message display */}
        {error && (
          <div
            className="error-banner"
            style={{
              backgroundColor: '#f8d7da',
              color: '#721c24',
              padding: '10px',
              borderRadius: '5px',
              marginBottom: '20px',
            }}
          >
            ❌ {error}
          </div>
        )}

        {/* Summary cards */}
        <div className="summary-cards">
          <div className="card">
            <h3>Total Income</h3>
            <p className="amount income">₹{stats.totalIncome.toFixed(2)}</p>
          </div>
          <div className="card">
            <h3>Total Expense</h3>
            <p className="amount expense">₹{stats.totalExpense.toFixed(2)}</p>
          </div>
          <div className="card">
            <h3>Balance</h3>
            <p className={`amount ${stats.balance >= 0 ? 'income' : 'expense'}`}>
              ₹{stats.balance.toFixed(2)}
            </p>
          </div>
        </div>

        {/* Action buttons */}
        <div className="action-buttons">
          <button
            className="btn-primary"
            onClick={() => setShowForm(!showForm)}
            disabled={loading}
          >
            {showForm ? 'Hide Form' : '+ Add Transaction'}
          </button>
        </div>

        {/* Transaction form (conditional display) */}
        {showForm && (
          <div className="form-section">
            <TransactionForm onTransactionAdded={handleTransactionAdded} />
          </div>
        )}

        {/* Loading state */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: '20px' }}>
            <p>Loading transactions...</p>
          </div>
        ) : transactions.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '20px' }}>
            <p>No transactions yet. Add one to get started!</p>
          </div>
        ) : (
          // Transaction list
          <div className="transactions-section">
            <h2>Recent Transactions</h2>
            <TransactionList
              transactions={transactions}
              onDelete={handleDelete}
            />
          </div>
        )}
      </div>
    </div>
  );
}

export default Dashboard;
